import{H as e,_t as t,it as n,rt as r}from"./chunks/framework.Bcve9O8f.js";var i=JSON.parse(`{"title":"Accreditation dossier","description":"ISO/IEC 17025 & 17065 conformance dossier — the deposit's technical evidence mapped to each clause group, with the residual an accredited body must grant.","frontmatter":{"title":"Accreditation dossier","description":"ISO/IEC 17025 & 17065 conformance dossier — the deposit's technical evidence mapped to each clause group, with the residual an accredited body must grant.","head":[["meta",{"name":"robots","content":"index, follow"}],["meta",{"property":"og:title","content":"Accreditation dossier | Millennium Solutions"}],["meta",{"property":"og:description","content":"ISO/IEC 17025 & 17065 conformance dossier — the deposit's technical evidence mapped to each clause group, with the residual an accredited body must grant."}],["meta",{"property":"og:url","content":"https://ceccec.psg.bg/millennium-solutions/accreditation.html"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"name":"twitter:title","content":"Accreditation dossier | Millennium Solutions"}],["meta",{"name":"twitter:description","content":"ISO/IEC 17025 & 17065 conformance dossier — the deposit's technical evidence mapped to each clause group, with the residual an accredited body must grant."}],["link",{"rel":"canonical","href":"https://ceccec.psg.bg/millennium-solutions/accreditation.html"}],["link",{"rel":"alternate","hreflang":"en","href":"https://ceccec.psg.bg/millennium-solutions/accreditation.html"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://ceccec.psg.bg/millennium-solutions/accreditation.html"}]]},"headers":[],"relativePath":"accreditation.md","filePath":"accreditation.md"}`),a={name:`accreditation.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="iso-iec-17025-17065-—-accreditation-dossier" tabindex="-1">ISO/IEC 17025 &amp; 17065 — accreditation dossier <a class="header-anchor" href="#iso-iec-17025-17065-—-accreditation-dossier" aria-label="Permalink to “ISO/IEC 17025 &amp; 17065 — accreditation dossier”">​</a></h1><blockquote><p><strong>Prepares the dossier; does not grant the accreditation.</strong> This maps the deposit&#39;s technical evidence to each clause group of the laboratory-competence (17025) and product-certification (17065) standards. Where a clause is met by kernel evidence it is <strong>supplied</strong> with its receipts; where only an accredited body or a physical facility can grant it, that part is the <strong>residual</strong>. The honest floor: a deposit can be technically conformant and still need the body&#39;s assessment and stamp — that stamp is the <code>/iso-conformance</code> accredited leaf.</p></blockquote><p><strong>8 supplied · 4 partial · 2 residual.</strong> The residual is the path: take this dossier to an accredited laboratory (17025) and certification body (17065).</p><h2 id="clause-map" tabindex="-1">Clause map <a class="header-anchor" href="#clause-map" aria-label="Permalink to “Clause map”">​</a></h2><table tabindex="0"><thead><tr><th>Std</th><th>Clause</th><th>Requirement</th><th>State</th><th>What the deposit supplies</th><th>Residual (accredited body)</th></tr></thead><tbody><tr><td>17025</td><td>4.1</td><td>Impartiality</td><td>◧ partial</td><td>the content-address is author-independent — anyone recomputes the result without trusting the author</td><td>the body&#39;s impartiality assessment and committee</td></tr><tr><td>17025</td><td>4.2</td><td>Confidentiality</td><td>✅ supplied</td><td>public deposit; no client data; CC BY-NC-ND licence states handling</td><td>—</td></tr><tr><td>17025</td><td>6.4</td><td>Equipment</td><td>◧ partial</td><td>the apparatus is specified (chip sketch qpu_arith.v + ℤ[ω] theorems)</td><td>physical equipment and its records at the lab</td></tr><tr><td>17025</td><td>6.5</td><td>Metrological traceability</td><td>✅ supplied</td><td>exact-integer arithmetic, no float; CHSH traces to the Tsirelson bound 2√2 and ISO units — receipts 6f5bb0ee-7cb2, e4044e10-ff4b…</td><td>physical calibration certificates for the device</td></tr><tr><td>17025</td><td>7.2</td><td>Methods &amp; validation</td><td>✅ supplied</td><td>every method is a kernel-decided theorem, validated by the Lean kernel — receipts 714d47e5-954e, 54b285c2-1cf7…</td><td>—</td></tr><tr><td>17025</td><td>7.5</td><td>Technical records</td><td>✅ supplied</td><td>the sealed ledger: every result content-addressed with a chained receipt, immutable and reproducible</td><td>—</td></tr><tr><td>17025</td><td>7.6</td><td>Measurement uncertainty</td><td>✅ supplied</td><td>the decision rule carries ZERO float uncertainty — CHSH S&gt;2 is decided on exact integers; physical shot-noise lives only in the counts</td><td>—</td></tr><tr><td>17025</td><td>7.7</td><td>Ensuring validity of results</td><td>✅ supplied</td><td>the gates (reconcile, recompute, the pre-commit court) re-verify every result each build</td><td>the body&#39;s proficiency testing</td></tr><tr><td>17025</td><td>7.8</td><td>Reporting of results</td><td>✅ supplied</td><td>the automated /iso-conformance and /chsh-run reports, generated from the evidence</td><td>—</td></tr><tr><td>17025</td><td>7.11</td><td>Control of data</td><td>✅ supplied</td><td>content-addressing makes every datum tamper-evident; a changed value changes its address</td><td>—</td></tr><tr><td>17025</td><td>8</td><td>Management system</td><td>◧ partial</td><td>the pipeline + gates are the quality-management system, enforced on every commit</td><td>the documented QMS the body audits</td></tr><tr><td>17065</td><td>7</td><td>Certification scheme (product)</td><td>◧ partial</td><td>the product (the qpu construction) is specified and its claims decided; the scheme criteria map to the sealed theorems</td><td>the certification body runs the scheme and issues the certificate</td></tr><tr><td>17065</td><td>4.1</td><td>Impartiality of certification</td><td>❌ residual</td><td>the evidence is independently recomputable</td><td>an accredited certification body, independent of the depositor</td></tr><tr><td>17065</td><td>6</td><td>Resource (certification personnel)</td><td>❌ residual</td><td>—</td><td>competent, accredited certification personnel at the body</td></tr></tbody></table><h2 id="the-path-to-the-stamp" tabindex="-1">The path to the stamp <a class="header-anchor" href="#the-path-to-the-stamp" aria-label="Permalink to “The path to the stamp”">​</a></h2><ol><li><strong>Technical dossier (ready now):</strong> the 8 supplied clauses — methods validated by the kernel, records in the sealed ledger, traceability on exact integers, data tamper-evident, results auto-reported. These are the evidence an assessor reads.</li><li><strong>Partial clauses:</strong> supply the institutional half — the documented QMS, equipment records, impartiality arrangements — around the technical core already in place.</li><li><strong>Residual (the body only):</strong> engage an accredited laboratory (17025) and certification body (17065); their independent assessment and certificate close the <code>/iso-conformance</code> accredited leaf. No code grants this, and this dossier does not pretend to.</li></ol><h2 id="honest-floor" tabindex="-1">Honest floor <a class="header-anchor" href="#honest-floor" aria-label="Permalink to “Honest floor”">​</a></h2><p>Technical conformance is necessary, not sufficient, for accreditation: the standards require an independent accredited body. This dossier makes the deposit&#39;s half auditable and complete; the stamp remains the body&#39;s act, named and reachable — the accredited leaf flips when the certificate exists, not before.</p>`,9)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};